(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0011.js"] = [{"id":"glyph-kai-8845","script":"kai","character":"衅","reading":"xìn","description":"⒈〈古〉一种祭祀仪式，用牲畜的血涂在新制的器物上～鼓。～钟。〈引〉涂抹～面。\n⒉缝隙，破绽乘～。〈引〉争端，事端挑～。寻～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衅"},{"id":"glyph-kai-884c","script":"kai","character":"行","reading":"xíng；háng","description":"xíng：行走、行动、实行；也指品行。háng：行列、行业；某些营业机构，如银行。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-884d","script":"kai","character":"衍","reading":"yǎn","description":"yǎn：(1)延长，开展～绎。～生。推～。展～。敷～。～生物。\n(2)多余的（指文字）～文（书籍中因缮写、刻板、排版错误而多出来的字句）。\n(3)低而平坦之地～沃（土地平坦肥美。亦作沃衍”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衍"},{"id":"glyph-kai-8854","script":"kai","character":"衔","reading":"xián","description":"口含\n怀藏\n奉接,接受\n把两物互相接起来或缚住\n包含,\n⒈马嚼子勒紧～。\n⒉用嘴含，包含，含有结草～环。～花。～远山。\n⒊藏在心中，怀恨～悲。～恨。\n⒋奉，接受～命。\n⒌相接～接。\n⒍职位，职称职～。头～。官～。军～。大使～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衔"},{"id":"glyph-kai-8857","script":"kai","character":"街","reading":"jiē","description":"jiē：(1)两边有房屋的、比较宽阔的道路，通常指开设商店的地方～道。～市。～巷。～坊。\n(2)方言，集市赶～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-街"},{"id":"glyph-kai-8859","script":"kai","character":"衙","reading":"yá","description":"yá：(1)旧时官署之称公～。～门。～参（cān）（官吏到上司衙门，排班参见，禀白公事）。～役。\n(2)唐代皇帝前殿元和十五年正月……群臣始朝于宣政～”。\n(3)排列成行的事物槐～。柳～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衙"},{"id":"glyph-kai-8861","script":"kai","character":"衡","reading":"héng","description":"héng：(1)秤杆，泛指秤～器。～镜（借指辨别是非善恶的标准）。～鉴（衡镜）。\n(2)称量～钧（借指执掌国政之权）。\n(3)反复思索做出决定，比较评定权～。～情度理。\n(4)平，对等平～。均～。\n(5)指北斗星～汉（北斗星和银河）。\n(6)古同横”，纵横。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衡"},{"id":"glyph-kai-8863","script":"kai","character":"衣","reading":"yī","description":"yī：(1)人穿在身上用以蔽体的东西～服。～着（zhuó）。～冠。～架。～锦还（huán）乡。\n(2)披或包在物体外面的东西炮～。糖～。肠～。\n(3)中医把胎盘和胎膜统称为胞衣”。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衣"},{"id":"glyph-kai-8865","script":"kai","character":"补","reading":"bǔ","description":"修补;整修破旧的东西\n补充\n①添上材料，修复破损的东西～衣服。\n③补养滋～。\n④利益；用处于事无～。\n【补白】报刊上填补空白的短文。\n【补集】在研究集合与集合之间的关系时，这些集合常常是某一个给定的集合的子集，这个给定的集合叫全集。用符号i表示。\n【补角】两角的和是平角，那么其中的一个角叫做另一个角的补角，即a+b=180°，a和b互为补角。\n【补苴罅漏】补好裂缝，堵住漏洞。比喻弥补缺漏。苴用草铺垫鞋底。罅孔隙。\n【补偏救弊】补救偏差疏漏，纠正缺点错误。\n【补体】人和动物新鲜血清中的一组球蛋白。单独不作用于抗体或抗原，被抗体抗原复合物等激活后，有促进吞噬、加强炎症反应作用，可扩大机体的免疫应答。\n【补叙】叙述方法之一。在叙述过程中对有关情况、事物作简要的、片断性的解释或说明，对原来的叙述起着补充、丰富的作用。\n【补遗】\n【补益】\n①益处。\n②产生益处。\n【补语】谓语后面或其它动词形容词性中心语后面的补充说明成分。表示动作的情况、结果、数量、性状的程度等。常作补语的是形容词和副词。如'来得快'中的'快'。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-补"},{"id":"glyph-kai-8868","script":"kai","character":"表","reading":"biǎo","description":"①事物的外表～皮、～里不一。\n②表亲～叔、～姐。\n③表示略～心意。\n④用药物把感受的风寒发散出来～寒气。\n⑤榜样；模范～率、为人师～。\n⑧古代测日影的标杆。参见【圭表】。\n⑨计时、测量的器具钟～、体温～、水～。\n【表白】向人表明自己的意思自我～。\n【表达式】用运算符号把数、变量等连接起来构成的式子。\n【表里如一】比喻人的思想和言行相一致。\n【表露】流露；显示出来。\n【表面波】见【地波】。\n【表面化学】研究在不均相物系中，存在于异相界面间的物理和化学现象的一门学科。如在固-气、固-液、液-气等界面间的吸附作用、接触作用、电动现象等。\n【表面积】物体表面的面积总和。\n【表面文章】比喻只讲空话，不办实事这个人就会做～。\n【表面张力】液体表面相邻两部分间单位长度内的相互牵引力。是分子力的一种表现。其大小与液体的性质、纯度和温度有关。由于表面张力的作用，液体表面积总是收缩到尽\n可能小。\n【表皮】动植物体表面的起保护等作用的组织。\n【表率】好的榜样他是我们年轻人的～。\n【表现手法】见【艺术手法】。\n【表现型】基因型在一定条件下所表达的性状总和。是基因型的表现形式，但表现型相同，基因型不一定相同。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-表"},{"id":"glyph-kai-886b","script":"kai","character":"衫","reading":"shān","description":"shān：上衣，单褂长～。衬～」～。棉毛～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衫"},{"id":"glyph-kai-886c","script":"kai","character":"衬","reading":"chèn","description":"附在衣服鞋帽里的布\n垫,衬垫\n施舍,布施\n衬托\n相帮\n①在里面托一层～一点纸。\n②衬在里面的～衣、西服、布。\n③附在衣裳、鞋、帽等某一部分的布制品帽～。\n④映衬；衬托绿叶、红花。\n【衬托】利用事物间的近似或对立的条件、用一些事物为陪衬来突出所要表现的事物的写作手法。它可以使被陪衬事物显得更加突出、形象，富有艺术魅力，是情节构造、意境\n创造、人物描写等的有效手法。衬托有正衬、反衬两类利用事物的相似条件来衬托的是正衬；利用事物的相反条件来衬托的是反衬。\n【衬字】歌词里为使韵律优美或表达意境的需要而增加的没有实义的字。如'风吹那个雪花满天飘'中的'那个'。\n⒈里面的，托在里面的～衣。～上一层棉絮。\n⒉配搭，从旁帮助～托。帮～。相互映～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衬"},{"id":"glyph-kai-8870","script":"kai","character":"衰","reading":"shuāi；cui","description":"shuāi：事物发展转向微弱～微。～弱。～老。盛（shèng）～。兴（xīng）～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衰"},{"id":"glyph-kai-8877","script":"kai","character":"衷","reading":"zhōng","description":"zhōng：(1)内心由～。苦～。无动于～。～肠。\n(2)福，善降～于下民”。\n(3)正中不偏折～。\n(4)贴身的内衣。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衷"},{"id":"glyph-kai-8881","script":"kai","character":"袁","reading":"yuán","description":"yuán：姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-袁"},{"id":"glyph-kai-8884","script":"kai","character":"袄","reading":"ǎo","description":"皮衣之类的御寒衣服\n泛指上衣。如棉袄;夹袄","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-袄"},{"id":"glyph-kai-888b","script":"kai","character":"袋","reading":"dài","description":"dài：(1)用布或皮做的盛东西的器物～子。布～。衣～。口～。旅行～。\n(2)量词，用于袋装的东西和水烟、旱烟一～儿面粉。一～烟。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-袋"},{"id":"glyph-kai-888d","script":"kai","character":"袍","reading":"páo","description":"páo：(1)中式长衣～子。长～。旗～。棉～。皮～。同～（旧时军人相称）。～泽（袍”和泽”均为古代衣服，后以此称军队中的同事，如～～之谊”、～～故旧”）。\n(2)衣服的前襟反袂拭面，涕沾～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-袍"},{"id":"glyph-kai-8896","script":"kai","character":"袖","reading":"xiù","description":"xiù：(1)衣服套在胳膊上的部分～子。套～。～标。\n(2)藏在袖子里～藏。～手旁观。～刃（袖藏利刃）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-袖"},{"id":"glyph-kai-889c","script":"kai","character":"袜","reading":"wà","description":"针织或编织的足套,袜子\n穿袜子\n袜mò 1.即抹胸。俗称兜肚。 2.掩盖;覆蔽。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-袜"},{"id":"glyph-kai-88ab","script":"kai","character":"被","reading":"bèi；pī","description":"bèi：(1)睡觉时覆盖身体的东西～子。～单。棉～。毛巾～。羽绒～。～褥。\n(2)盖，遮覆～覆。泽～后世（恩惠遍及后代）。\n(3)遭遇，遭受～灾。～难（nàn）。\n(4)介词，用在句中表示主讲是受事者他～（老板）辞退了。\n(5)用在动词前，表示受动～动。～告。～批评。～剥削。\npī：古同披”，覆盖。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-被"},{"id":"glyph-kai-88ad","script":"kai","character":"袭","reading":"xí","description":"衣一套为一袭\n⒈乘人不备而攻击～击。夜～。奇～。\n⒉因循，继承，照样做因～。世～。抄～。沿～。\n⒊侵入侵～‘气～人。\n⒋量词。一副，一套衣服一～。一～被褥。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-袭"},{"id":"glyph-kai-88b1","script":"kai","character":"袱","reading":"fú","description":"妇女的包头巾\n包袱\n中的笑料抖包～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-袱"},{"id":"glyph-kai-88c1","script":"kai","character":"裁","reading":"cái","description":"cái：(1)用剪子剪布或用刀子割纸～剪。～缝。～衣。对～。\n(2)减除，去掉一部分～减。～军。～员。\n(3)决定，判断～判。～夺（考虑决定）。～决。～度（duó）。～断。\n(4)安排取舍体～。别～。独出心～。\n(5)节制，抑止制～。独～。\n(6)杀自～。\n(7)古同才”，仅，方。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-裁"},{"id":"glyph-kai-88c2","script":"kai","character":"裂","reading":"liè；liě","description":"liè：破开，开了缝（fèng）～开。～纹。～缝。～痕。～变（原子核分裂成几个其他原子核，并放出中子的过程）。～隙。～罅（裂缝）。分～。破～。决～。割～。扯～。\nliě：物体的两部分向两旁分开～着怀。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-裂"},{"id":"glyph-kai-88c5","script":"kai","character":"装","reading":"zhuāng","description":"服装\n亦泛指物品\n⒈行李行～。整～待发。\n⒉打扮，又指演员的打扮～扮。乔～。化～。卸～。\n⒊安置，盛放～置。～箱。～载。～船。～货。安～。～电话。\n⒋修配或组合成整体～修。～配。组～。\n⒌衣服服～。中山～。春秋～。\n⒍修饰，裱衬～饰。～点。～裱。～潢。\n⒎订制成册、籍～订。精～。平～本。\n⒏假作，故意做作假～。～模作样。～聋作哑。～腔作势。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-装"},{"id":"glyph-kai-88d5","script":"kai","character":"裕","reading":"yù","description":"yù：(1)丰富，宽绰宽～。富～。充～。节用～民。\n(2)从容，不紧张费力应付～如。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-裕"},{"id":"glyph-kai-88d9","script":"kai","character":"裙","reading":"qún","description":"qún：(1)一种围在腰以下的服装～子。～钗。筒～。连衣～。百褶～。\n(2)像裙子的东西墙～。鳖～。～礁（海岸边的珊瑚礁）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-裙"},{"id":"glyph-kai-88e4","script":"kai","character":"裤","reading":"kù","description":"穿在腰部以下、分别套住两腿的衣物。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-88f3","script":"kai","character":"裳","reading":"shang；cháng","description":"cháng：古代指遮蔽下体的衣裙。\n〔～～〕光明。\nsh：〔衣～〕衣服。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-裳"},{"id":"glyph-kai-88f8","script":"kai","character":"裸","reading":"luǒ","description":"luǒ：露出，没有遮盖～露。～体。～裎（脱衣露体）。赤～～。～子植物。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-裸"},{"id":"glyph-kai-88f9","script":"kai","character":"裹","reading":"guǒ","description":"guǒ：(1)包；缠绕～脚。把这包糖～好。～足不前。\n(2)夹带；夹杂不该把次货～进去卖∶人坏人～在一起一时分不清。\n(3)方言，吸（奶）小孩生下来就会～奶。奶头被这孩子～得生疼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-裹"},{"id":"glyph-kai-8902","script":"kai","character":"褂","reading":"guà","description":"guà：上身的衣服～子。马～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-褂"},{"id":"glyph-kai-8910","script":"kai","character":"褐","reading":"hè","description":"hè：(1)粗布或粗布衣服短～。\n(2)黑黄色～煤（煤的一种，多为褐色，除可作燃料外，还可以提炼汽油、煤油、焦油等。亦称褐炭”）。～藻（藻类植物的一大类，褐色，是海底最主要的藻类，富含碘质和胶质，海带就是供食用的褐藻）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-褐"},{"id":"glyph-kai-8912","script":"kai","character":"褒","reading":"bāo；bǎo","description":"bǎo：(1)赞扬，夸奖，与贬”相对～奖。～扬。～贬。～义词。\n(2)衣襟宽大～衣博带。\n(3)中国周代诸侯国名，在今陕西省勉县东南。亦称有褒”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-褒"},{"id":"glyph-kai-8925","script":"kai","character":"褥","reading":"rù","description":"rù：睡觉时垫在身体下面的东西，用棉絮、兽皮或电热材料等制成～子。～单。～疮。电～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-褥"},{"id":"glyph-kai-892a","script":"kai","character":"褪","reading":"tuì；tùn","description":"tùn：(1)使穿着的衣服或套着的东西脱离把袖子～下来。\n(2)向内退缩而藏起来把手～在袖子里。\n(3)后退，逃脱不要遇事就往后～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-褪"},{"id":"glyph-kai-895f","script":"kai","character":"襟","reading":"jīn","description":"jīn：(1)衣服的胸前部分大～。对～。底～。～带（亦喻山川屏障环绕，地势险要）。～要（亦喻军事上险要的地理位置）。\n(2)胸怀，抱负～怀。胸～。\n(3)姐妹的丈夫之间的称呼连～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-襟"},{"id":"glyph-kai-897f","script":"kai","character":"西","reading":"xī","description":"xī：(1)方向，太阳落下的一边，与东”相对～面。～晒。～域。～方。～席（旧时对幕友或家塾教师的敬称。古代主位在东，宾位在西。亦称西宾”）。～宫（借指妃嫔）。\n(2)事物的样式或方法属于西方的（多指欧美各国）～学。～画。～餐。～医。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-西"},{"id":"glyph-kai-8981","script":"kai","character":"要","reading":"yào；yāo","description":"yào：(1)索取～账。～价。\n(2)希望，想～强。～好。\n(3)请求她～我给她读报。\n(4)重大，值得重视的重～。～人。～领。纲～。～言不烦。\n(5)应该，必须须～。\n(6)将（jiāng）将～。快～。\n(7)如果，倘若～是。\n(8)表选择～么。～不。～不然。\nyāo：(1)求，有所倚仗而强求～求。～挟。\n(2)古同腰”。\n(3)古同邀”，中途拦截。\n(4)古同邀”，约请。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-要"},{"id":"glyph-kai-8986","script":"kai","character":"覆","reading":"fù","description":"fù：(1)遮盖，蒙～盖。～溺。～蔽。～被（遮盖，喻恩荫）。～庇。\n(2)翻，倾倒，败，灭～舟。颠～。～灭。～辙（翻过车的道路，喻曾经失败的做法）。～没（mò）。～水难收。～巢无完卵（喻灭门之祸，无一得免，亦喻整体覆灭，个人不能幸存）。前车之～，后车之鉴。\n(3)同复”①②。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-覆"},{"id":"glyph-kai-89c1","script":"kai","character":"见","reading":"jiàn","description":"歧王宅里寻常见\n⒈看到看～。耳闻目～。〈引〉接触，遇到胶卷忌讳～光。病刚好，不要～寒。\n⒉看得出，显现出初～成效。已～分晓。\n⒊会面，会晤会～。接～。\n⒋看法，认识，扩大知识～解。～识。远～。不固执己～。\n⒌指明出处～上页。\n⒍助词。\n①用在动词前，〈表〉被动莫～笑。别～怪。\n②用在动词前，〈表〉对说话人怎么样～教。请～谅。\n⒎用在\"听\"、\"闻\"、\"看\"等动词后，〈表〉效果听～了。看～了。\n⒏［见习］学得专业知识的人刚到工作岗位去，现场实地工作实习～习生。\n⒐［见证］亲眼看到，可以作证的人。也指可以作证的事物。\n⒈显出，出现，显露表～。华佗再～。昙花一～。\n见\"儋藍\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-见"},{"id":"glyph-kai-89c2","script":"kai","character":"观","reading":"guān","description":"⒈看～看。～赏。登楼～望。袖手旁～。\n⒉对事物的认识或看法世界～。正确的～点。她很乐～。\n⒊看到的景物和景象美～。奇～。\n⒉楼台之类台～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-观"},{"id":"glyph-kai-89c4","script":"kai","character":"规","reading":"guī","description":"法度、准则\n必将\n⒈画圆形的工具圆～。两脚～。\n⒉法则，章程，惯例～则。～章。常～办理。革除陋～。\n⒊劝告，告诫～劝。～谏。\n⒋谋划，制定，决定～划。～定。\n①俗成或规定的标准广告应该～范化。\n②合乎一定的标准课本语文，必须～范化。\n①画圆形与方形的两种工具。\n②规章制度循～蹈矩。\n③行为端正老实～ ～矩矩。\n规guì 1.见\"规规\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-规"},{"id":"glyph-kai-89c5","script":"kai","character":"觅","reading":"mì","description":"偷窃","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-觅"},{"id":"glyph-kai-89c6","script":"kai","character":"视","reading":"shì","description":"⒈看～力。～若无睹。\n⒉看待，看作轻～。～如寇仇。～少如长。\n⒊观察，察看～察。巡～。\n⒋活，生存长生久～。\n①眼睛与所看目标之间的假想直线。\n②眼睛所能看到的。〈喻〉注意的方向或目标她的话是在转移大家的～线。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-视"},{"id":"glyph-kai-89c8","script":"kai","character":"览","reading":"lǎn","description":"观赏\n览làn 1.唐代南诏副将官职名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-览"},{"id":"glyph-kai-89c9","script":"kai","character":"觉","reading":"jué；jiào","description":"jué：感觉、察觉；醒悟。jiào：睡眠，如睡觉、午觉。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-89d2","script":"kai","character":"角","reading":"jiǎo；jué","description":"jiǎo：(1)牛、羊、鹿等头上长出的坚硬的东西牛～。鹿～。犄～。～质。\n(2)形状像角的菱～。皂～。\n(3)突入海中的尖形的陆地（多用于地名）成山～（在中国山东省）。\n(4)几何学指从一点引出两条直线所夹成的平面部分直～。～度。～钢。～尺。\n(5)物体边沿相接的地方～落。\n(6)额骨（俗称额角”）。\n(7)古代未成年男孩头顶两侧束发为髻（亦称总角”）。\n(8)古代军中的一种乐器画～∨～。\n(9)古代量器，酒的计量单位先取两～酒来”。\n(10)中国货币单位。\n(11)星名，二十八宿之一。\n(12)量词。\njué：(1)古代酒器，青铜制，形似爵而无柱，两尾对称，有盖，用以温酒和盛酒。\n(2)演员，或指演员在戏剧中所扮演的人物～色。名～。\n(3)较量，竞争～力。～斗。～逐。\n(4)古代五音之一，相当于简谱3”。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-角"},{"id":"glyph-kai-89e3","script":"kai","character":"解","reading":"jiě；jiè；xiè","description":"jiě：(1)剖开，分开～剖。分～。瓦～。～体。\n(2)把束缚着、系着的东西打开～开。～甲归田。～囊相助。\n(3)除去，除，废除，停止～放（ａ．使广大人民群众脱离压迫；ｂ．解除束缚而得到自由）。～除。～饿。～乏。～惑。～疑。～围。～脱。～雇。～聘。～散。～毒。\n(4)溶化溶～。～冻。\n(5)讲明白，分析说明～释。～析。～说。劝～。～嘲。\n(6)懂，明白理～。见～。\n(7)调和，处理～决⊥～。调（tiáo）～。排～。\n(8)高兴，开心～颜而笑。\n(9)排泄～手。\n(10)代数方程中未知数的值。\n(11)演算方程式～方程。\n(12)文体的一种，如韩愈《进学解》。\n系；结；\njiè：(1)发送。\n(2)押送财物或犯人押～。起～。～差（chāi）。～回北京。\n系；结；\nxiè：(1)古同懈”，松弛，懈怠。\n(2)古同邂”，邂逅。\n(3)旧时指杂技表演的各种技艺，特指骑在马上表演的技艺卖～的。跑马卖～。\n(4)姓。\n〔～湖〕湖名，在中国山西省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-解"},{"id":"glyph-kai-89e6","script":"kai","character":"触","reading":"chù","description":"用角抵人或物\n撞,碰\n接触\n遇到;遭受\n①接触；碰～电、一～即发。\n②触动；感动；感～、忽有所～。\n【触机】触动灵机不假思索～即发。\n【触角】〈生〉通常指动物头部细长的感觉器官。在节肢动物中由附肢变成。具触觉、嗅觉功能。有的种类还具其他多种功能。\n【触景生情】为眼前的景物所触动而产生某种情感。\n【触觉】〈生〉机械刺激引起的皮肤感觉。狭义指刺激轻轻接触皮肤所引起的肤觉。广义还包括压觉和振动觉。盲聋哑人的触觉多有高度的发展，以补偿听觉和视觉缺陷。\n【触类旁通】掌握某种知识或规律后，推知相关的知识或规律。旁通互相贯通。\n【触目惊心】见【怵目惊心】。\n【触目伤怀】看到某种事物而引起内心伤感。\n【触手】〈生〉无脊椎动物头部细长柔韧的突起物。主要作触觉和卷攫用，间或也有呼吸、运动、支持身体等功能。水螅、沙蚕、海参等都具触手。\n⒈抵，用角顶撞有角者～。\n⒉碰撞，碰着～动。～礁。～电。接～。～目惊心。\n⒊冒犯～犯。～怒。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-触"},{"id":"glyph-kai-8a00","script":"kai","character":"言","reading":"yán","description":"yán：(1)讲，说～说。～喻。～道。～欢。～情。～必有中（zhòng）（一说就说到点子上）。\n(2)说的话～论。～辞（亦作言词”）。语～。～语。～简意赅。\n(3)汉语的字五～诗。七～绝句。洋洋万～。\n(4)语助词，无义～归于好。～告师氏，～告～归”。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-言"},{"id":"glyph-kai-8a89","script":"kai","character":"誉","reading":"yù","description":"通举”。推荐\n荣誉,美名\n⒈名声名～。声～。荣～。\n⒉特指好的名声～满全球。\n⒊赞扬，赞美称～。～不绝口。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-誉"},{"id":"glyph-kai-8a8a","script":"kai","character":"誊","reading":"téng","description":"照原稿抄写清楚","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-誊"},{"id":"glyph-kai-8a93","script":"kai","character":"誓","reading":"shì","description":"shì：(1)当众或共同表示决心，依照说的话实行～师。～词。～愿。～死。\n(2)表示决心的话发～。宣～。立～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-誓"},{"id":"glyph-kai-8b66","script":"kai","character":"警","reading":"jǐng","description":"jǐng：(1)注意可能发生的危险，戒备，告诫～卫。～世。～告。～戒。～备。～惕。～省（xǐng）（警惕醒悟）。\n(2)需要戒备的事件或消息～号。～报。～钟。\n(3)感觉敏锐，见解独到～句。～觉（jué）。机～。\n(4)国家维持社会秩序和治安的武装力量～察。～士。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-警"},{"id":"glyph-kai-8b6c","script":"kai","character":"譬","reading":"pì","description":"pì：(1)打比方～如。～犹。～若。～语。～喻（比喻）。\n(2)领悟。\n(3)晓谕～解。～说（晓示述说）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-譬"},{"id":"glyph-kai-8ba1","script":"kai","character":"计","reading":"jì","description":"⒈算，算帐，核算～算。共～。～日程功。\n⒉测量或检算度数、时间等的仪表温度～。记时～。\n⒊谋略，策略～谋。～策。～巧。妙～。奇～。\n⒋谋划，盘算～划。～出万全。父母之爱子，则为之～深远。\n①争论，较量跟他～较，没意思。\n②盘算，比较她从不～较个人得失。\n③商量，打算他们～较了半天，也没结果。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-计"},{"id":"glyph-kai-8ba2","script":"kai","character":"订","reading":"dìng","description":"改正,修正\n达成协议订立;使生效\n预先约定\n把零散的纸张、书页加工成本\n②约定～报。\n③修改；改正～正、校～。\n④用线、铁丝等把书页等连在一起装～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-订"},{"id":"glyph-kai-8ba4","script":"kai","character":"认","reading":"rèn","description":"看作;认为\n⒈识别，分辨～识。～字。～出。～清是非。\n⒉承担，接受，允许，同意承～。公～。～错。～可。\n⒊和无关系的人建立某种关系～义父。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-认"},{"id":"glyph-kai-8ba5","script":"kai","character":"讥","reading":"jī","description":"讽刺、挖苦，如讥笑、讥讽；也指规劝。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-8ba8","script":"kai","character":"讨","reading":"tǎo","description":"讨伐;诛戮\n⒈征伐，发动攻击～伐。征～。声～。\n⒉查究，整治检～。～军纪。\n⒊探求，研究探～。研～。\n⒋索取～债。～价还价。\n⒌求，请求，乞求～饶。～教。～饭。\n⒍招惹，引起～人厌恶。自～苦吃。～人喜欢。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-讨"},{"id":"glyph-kai-8ba9","script":"kai","character":"让","reading":"ràng","description":"退让;谦让\n允恭\n⒈不争，尽给旁人谦～。辞～。退～。〈引〉请把客人～进屋里来。特指让位、让权～贤。\n⒉将东西转给别人转～。廉价出～。\n⒊叫，许，使，任凭～他试试。～她去做。决不～国家财产受损失。～他们提意见。\n⒋被这本书～他弄坏了。泥土～雨水冲走了。\n⒌责备，责怪诮～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-让"},{"id":"glyph-kai-8bad","script":"kai","character":"训","reading":"xùn","description":"解说,注释。用通俗的话解释词语的意义\n但世人未之深亮训\n⒈教导，教诲～导。～练。吸取教～。\n⒉法则，规范，准则遗～。不足为～。\n⒊申斥～人。～诫。\n⒋词义解释～释。～诂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-训"},{"id":"glyph-kai-8bae","script":"kai","character":"议","reading":"yì","description":"评议是非\n选择\n议处;议罪\n⒈意见，言论，主张提～。异～。建～。\n⒉商量，讨论商～。～论。～定。～决。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-议"},{"id":"glyph-kai-8baf","script":"kai","character":"讯","reading":"xùn","description":"木讯\n⒈问，询问，特指审问～问。传～。审～。\n⒉音信，消息音～。通～。新华社～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-讯"},{"id":"glyph-kai-8bb0","script":"kai","character":"记","reading":"jì","description":"记载,记录\n记,书也。\n⒈思念，把所见、所闻等事物保持在脑子里，跟\"忘\"相对惦～。牢～。～性强。～得住。\n⒋印章图～。戳～。\n⒌标志～号。暗～。\n⒍量词他挨了两～耳光。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-记"},{"id":"glyph-kai-8bb2","script":"kai","character":"讲","reading":"jiǎng","description":"⒈谈，说～普通话。～故事。\n⒉解释，说明～解。～课。\n⒊注重，顾到，谋求～清洁。～政策。～团结。\n⒋商讨，商议～价。～条件。\n①注重，探求～究整洁。～究效益。\n②精致，美观这个实验室相当～究。\n③一定的方法、道理或值得注意的翻译外国文学，在技巧上是大有～究的。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-讲"},{"id":"glyph-kai-8bb3","script":"kai","character":"讳","reading":"huì","description":"隐;隐蔽\n⒈隐瞒，避忌，有顾忌不敢说或不愿说～莫如深。～疾忌医。无庸～言。不必忌～。\n⒉封建时代称死去了的皇帝或长者的名姓刘～邦。姓曹～操。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-讳"},{"id":"glyph-kai-8bb6","script":"kai","character":"讶","reading":"yà","description":"诧异,感到意外\n责怪\n讶yà惊奇，诧异惊～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-讶"},{"id":"glyph-kai-8bb8","script":"kai","character":"许","reading":"xǔ","description":"⒈应允，认可～可。允～。准～。\n⒉称赞赞～。推～。\n⒊预先答应给予～诺。以身～国。\n⒋可能，或者也～。或～。\n⒌处所，地方先生不知何～人也。\n⒍〈表〉约略估计的几～。只有少～。年七十～。\n⒎句末语气词。这样如～。一生长恨奈何～。\n⒏周代诸侯国名，在今河南省许昌一带。\n许hǔ 1.见\"许许\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-许"},{"id":"glyph-kai-8bb9","script":"kai","character":"讹","reading":"é","description":"字亦作讹”\n差错\n讹诈\n改变;感化\n变化\n①错误以～传～。\n②敲诈～人。\n【讹传】错误的传说。\n【讹音】错误的读音。\n【讹诈】\n①假借某种理由向人强行索取财物或其他权益。\n②威胁恫吓。\n讹é 1.虚假。 2.讹误;错谬。 3.怪异;怪诞。 4.妖言;谣言。 5.指徒歌;歌谣。 6.吓诈。 7.书法用语。 8.蛇的别名。 9.通\"吪\"。感化;改变。 10.通\"吪\"。行\n动;移动。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-讹"},{"id":"glyph-kai-8bba","script":"kai","character":"论","reading":"lùn","description":"论语\n议论, 分析和说明事理\n坐而论道。\n⒈商讨，判断，研究讨～。议～。评～。争～。就事～事。\n⒉主张，学说进化～。唯物～。\n⒊文体名。论述事物的内容、意义，阐明道理～文。社～。实践～。\n⒋衡量，评定～罪。\n⒌按照～件计酬。～质核价。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-论"},{"id":"glyph-kai-8bbc","script":"kai","character":"讼","reading":"sòng","description":"打官司\n⒈争论，争辩辩～。聚～纷纭。\n⒉在法庭上争辩，打官司～事。诉～。\n⒊公开未敢～言。\n⒋〈古〉通\"颂\"。赞美，颂扬。\n讼róng 1.容纳。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-讼"},{"id":"glyph-kai-8bbd","script":"kai","character":"讽","reading":"fěng","description":"婉言微辞或指责\n⒈用含蓄的话词劝告或讥刺谈笑～谏。～刺小品。挖苦讥～。\n⒉背书，不看着书本子念读～诵。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-讽"},{"id":"glyph-kai-8bbe","script":"kai","character":"设","reading":"shè","description":"⒈布置，装置，安排～置。～立。～防。\n⒉筹划，规划，制定方案、图样等～法。～想。～计。\n⒊假使，如果，若是，假想～若。～如。～或。假～。\n①工作上、生产上、生活上等所需要的各种设施和器械用品。\n②设置以备施用。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-设"},{"id":"glyph-kai-8bbf","script":"kai","character":"访","reading":"fǎng","description":"⒈询问，调查～贫济困。查～。采～。\n⒉探望～亲会友。相～。探～。拜～。〈引〉寻求～求。\n⒊查，侦察明察暗～。\n【访问】有目的地探望～问水稻专家。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-访"},{"id":"glyph-kai-8bc0","script":"kai","character":"诀","reading":"jué","description":"早知诀汝。\n通决”。自杀\n⒈辞别，多指长别，永别与母～。～别。永～。\n⒉窍门，高明的办法～窍。这是秘～。她有妙～。\n⒊使用事物的主要内容编成顺口的便于记忆的词句编口～。写歌～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诀"},{"id":"glyph-kai-8bc1","script":"kai","character":"证","reading":"zhèng","description":"谏正\n通症”。病症\n假借为徵”。今亦用为譪验字。证据\n⒈以人物、事实来表明或断定～人。～物。～明。～实。～几何题。\n⒉凭据，帮助断定的东西～据。物～。居民身份～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-证"},{"id":"glyph-kai-8bc4","script":"kai","character":"评","reading":"píng","description":"评判\n评语;评论的话\n⒈议论，分析阐明道理～议。～论。短～。\n⒉判定，比高低优劣～判。～定。～选。～比。\n⒊［评价］对人或事物估定价值和作用。\n⒋［评介］评论介绍。\n⒌［评阅］对试卷、作品等阅览及评定。\n⒍［评剧］也叫\"评戏\"。戏曲的一种，流行于华北、东北等地。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-评"},{"id":"glyph-kai-8bc6","script":"kai","character":"识","reading":"shí","description":"⒈知道，认得，能辨别～字。认～。～别。～途老马。\n⒉学问，应知的，所知道的学～。知～。常～。有～之士。\n⒊见解，辨别是非的能力见～。远见卓～。\n⒈记住，做记号，也指记号、标志博闻强～。表～。款～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-识"},{"id":"glyph-kai-8bc8","script":"kai","character":"诈","reading":"zhà","description":"假装;冒充\n⒉假装～败。～病。～降。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诈"},{"id":"glyph-kai-8bc9","script":"kai","character":"诉","reading":"sù","description":"告诉,说给人听\n吾与并\n⒈叙说叙～。～苦。详细～说。\n⒉控告～讼。上～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诉"},{"id":"glyph-kai-8bca","script":"kai","character":"诊","reading":"zhěn","description":"医生为断定疾症而察看病人身体内部、外部的情况门～。～断。～室。～脉。\n察看，验证匠石觉而～其梦”。\n诊zhěn看病，检查病人就～。～病。～断。随到随～。巡廻～治。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诊"},{"id":"glyph-kai-8bcd","script":"kai","character":"词","reading":"cí","description":"诗文中的词语\n①言词；词句歌～、～不达意。\n②一种韵文形式，由五言诗、七言诗和民歌发展而来，形成于唐代，盛行于宋代。有小令和慢词两种，一般分上下两阕。\n③语言中最小的有意义的可以自由运用的单位。\n【词不达意】所用词语不能清楚地表达意思。\n【词典】汇集语言里的词语，按某种次序排列，并一一加以解释的一种工具书。\n【词法】语言学上的形态学。内容包括词的构造、词的变化、词的分类等。\n【词根】体现基本意义的语素。如'师''杯'分别为、'老师'、'杯子'两词的词根。\n【词汇】\n①一种语言里所使用的词的总汇。\n②一部作品或一个人所用的词的总汇。\n【词类】词在语法上按照不同语法功能的分类。如名词、动词、形容词、副词等。\n【词类活用】甲类词在特定的条件下，为了表达上的需要，偶尔用作乙类。如'夏雨雨人'，第二个'雨'字活用为动词，念去声，'雨打'之意。\n【词类转化】指由一个词类转化为另一个词类。如英语的water，本为名词'水'，可以转化为动词'浇水'。\n【词令】见【辞令】。\n【词牌】填词用的曲调名。最初的词，为了配合音乐来歌唱，要按词制调或依调填词，曲调的名称要根据词的内容而定◇来多数词已不再配乐歌唱，词牌已变为填词时文字、\n音韵的结构定式。\n【词性】","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-词"},{"id":"glyph-kai-8bd1","script":"kai","character":"译","reading":"yì","description":"解释;阐述\n通择”。选择\n周道衰微,失爵亡邦,后嗣乖散,各\n①翻译。把一种语言文字转换成另一种语言文字。\n②指翻译人员。\n③指语言不通的异域。\n④阐述;诠释。\n⑤变易，改变。如\"译形借声\"。\n⑥通\"绎\"。寻绎。\n⑦通\"擇\"。选择。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-译"},{"id":"glyph-kai-8bd5","script":"kai","character":"试","reading":"shì","description":"尝试\n⒈按预定想法非正式的做～做。～车。～ ～看。\n⒉检验，品尝～验。尝～。\n⒊考，测验考～。口～。笔～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-试"},{"id":"glyph-kai-8bd7","script":"kai","character":"诗","reading":"shī","description":"⒈文体名。形式很多，它是可以歌咏或朗诵的韵文。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诗"},{"id":"glyph-kai-8bda","script":"kai","character":"诚","reading":"chéng","description":"真实\n②实在；的确；～然。\n【诚笃】诚实真挚。\n【诚惶诚恐】原为封建时代臣下给皇帝奏章中的套语，表示敬畏之意。形容十分谨慎恐慌不安的样子。有时含讽刺意味。\n【诚然】\n①实在；的确这本书～可以一读。\n【诚心诚意】实心实意。形容十分诚挚。\n【诚挚】诚恳真挚。\n⒈真心，不虚伪～实。～挚。～信。真～。～心～意。\n⒉确实，的确～然。～说此言。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诚"},{"id":"glyph-kai-8bdd","script":"kai","character":"话","reading":"huà","description":"话题\n话本;故事\n授意表达的言词\n⒈语言讲～。普通～。\n⒉说，谈～别离。茶～会。～不投机。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-话"},{"id":"glyph-kai-8bde","script":"kai","character":"诞","reading":"dàn","description":"虚妄;荒唐\n①出生～生。\n②生日～辰、华～。\n③荒唐的；不合情理的荒～、怪～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诞"},{"id":"glyph-kai-8be1","script":"kai","character":"诡","reading":"guǐ","description":"违反,自相矛盾\n⒈欺诈，奸滑～计。～辩。\n⒉奇异，怪异，出乎平常～谲。～殊。～秘。～异。\n⒊违反，违背～于常理。言行相～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诡"},{"id":"glyph-kai-8be2","script":"kai","character":"询","reading":"xún","description":"询xún问，请教，征求意见～问。探～。查～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-询"},{"id":"glyph-kai-8be5","script":"kai","character":"该","reading":"gāi","description":"同引申义\n广博\n包容;包括\n⒈应当应～。自己～做的事，一定要抓紧做好。\n⒉〈表〉从推测到必然的或可能的结果她～到家了。\n⒊欠～她的钱。\n⒋那，那个，特指前面说过的人或事物～人。～处。～事。\n⒌〈古〉同\"赅\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-该"},{"id":"glyph-kai-8be6","script":"kai","character":"详","reading":"xiáng","description":"详细说明\n清楚地知道\n⒈细密，完备～细。～尽。～情。～实。～议法令。\n⒉清楚，知道内容～知。\n⒊说明，细说～谈。内～。～告之。\n⒋广泛，周遍～找。\n⒍〈古〉通\"佯\"。假装。\n详yáng 1.诈，假装。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-详"},{"id":"glyph-kai-8beb","script":"kai","character":"诫","reading":"jiè","description":"规劝\n警诫\n规劝告诫之文\n⒈警告，劝告告～。劝～。～勉。\n⒉警戒，戒备前车覆，后车～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诫"},{"id":"glyph-kai-8bec","script":"kai","character":"诬","reading":"wū","description":"欺骗\n无中生有,捏造事实害人\n诬去贤使君。\n诬太守者。\n抹杀","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诬"},{"id":"glyph-kai-8bed","script":"kai","character":"语","reading":"yǔ","description":"交谈,说话\n既歌而语。\n⒈说，谈寡言少～。自言自～。\n⒉话，言论～言『～。外～。成～。\n⒊代替说话的动作手～。旗～。\n⒋简单的俗话或古句谚～。古～。～曰。\n⒌虫、鸟的鸣声蝉～。鸟～。\n语ｙù告诉莫～人。\n语yù 1.告诉。 2.通\"悟\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-语"},{"id":"glyph-kai-8bef","script":"kai","character":"误","reading":"wù","description":"谬误;错误\n耽误\n妨害\n⒈错，荒谬～差。～会。错～。谬～。\n⒉耽搁～事。～点。耽～。\n⒊使受害～人子弟。～国～民。\n⒋不是故意的但有害于人～伤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-误"},{"id":"glyph-kai-8bf1","script":"kai","character":"诱","reading":"yòu","description":"引诱\n向导,引\n⒈引导，教导，劝导～导。循循善～。\n⒉使用计策或手段迷惑、招引别人引～。利～。～骗。～惑。～敌深入。\n⒊吸引景色～人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诱"},{"id":"glyph-kai-8bf2","script":"kai","character":"诲","reading":"huì","description":"明示,诱使\n教导的话\n诲huì教导，指教教～。学而不厌，～人不倦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诲"},{"id":"glyph-kai-8bf4","script":"kai","character":"说","reading":"shuō；shui","description":"说服;劝说\n休憩;止息。通税”\n⒈〈古〉同\"悦\"。\n⒈说动别人，使他听从自己的意见～客。游～。\n⒈讲话，用话表达意思你～。～到做到。\n⒉言论，主张学～。著书立～。\n⒊批评，指责～了他几句。\n⒋解释解～。一～就懂。\n说tuō 1.简易。参见\"说唃\"。 2.通\"脱\"。解脱;免除。 3.通\"脱\"。急骤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-说"},{"id":"glyph-kai-8bf5","script":"kai","character":"诵","reading":"sòng","description":"⒈背读，用抑扬高低的腔调念背～。朗～。\n⒉述说，陈述～功。\n⒊诗篇作～。\n⒋〈古〉通\"讼\"。公开。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诵"},{"id":"glyph-kai-8bf7","script":"kai","character":"请","reading":"qǐng","description":"通情”。情况,实情\n请求;要求\n⒈求，请求～示。～假。～命。～战。\n⒉敬词。用于动词前～进。～坐。～喝茶。\n⒊邀请，邀约，延聘～客。～医师。～专家指导。聘～教师。\n请qìng 1.朝会名。\n请qíng 1.后又作\"?\"。认领;接受。 2.通\"情\"。实情;情况。 3.通\"情\"。实在;的确。 4.通\"情\"。情感。\n请qīng 1.参见\"请靓\"﹑\"请室\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-请"},{"id":"glyph-kai-8bf8","script":"kai","character":"诸","reading":"zhū","description":"众;各\n诸将皆失色。\n仆必能从\n⒈各，众，许多～军。～位。～君。～子百家。\n诸chú 1.蟾蜍。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诸"},{"id":"glyph-kai-8bfa","script":"kai","character":"诺","reading":"nuò","description":"古时批字于公文之尾,表示许可叫诺”,犹今签字\n诺贝尔\n⒈答应，应允～言。\n⒉答应声，〈表〉同意～～连声。唯唯～～","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诺"},{"id":"glyph-kai-8bfb","script":"kai","character":"读","reading":"dú","description":"籀书,抽释理解书的意义\n阅读\n读 dòu语句中的停顿。古代诵读文章时，完整的长句或小段的停顿称为'句'，'句'中的小停顿称为'读'。又见dú。\n①照着文字念。\n②阅读；看书或文章。\n②上学～大学。又见dòu。\n【读后感】一种文体。读书看报之后，把心得、感受、看法等写成文章或笔记。\n【读卖新闻】日本最有影响的报纸之一。1874年创刊。面向大众，注重社会新闻和体育新闻。每天早刊24版，晚刊12版。\n【读秒】\n①围棋、象棋等体育比赛规则。对局者自由支配时间已用到事先规定的保留时限后始由裁判员报时。\n②比喻非常紧张繁忙的状态或阶段亚运工程已进入～阶段。\n【读数据语句】〈计〉basic语言语句之一。它向运行中的程序的某些变量提供数据。date语句设置数据表，由read语句提取数据，每提取一个数据时，指向下一个将要提取的\n数据位置。\n【读友】〈港台〉读者。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-读"},{"id":"glyph-kai-8bfd","script":"kai","character":"诽","reading":"fěi","description":"毁谤","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诽"},{"id":"glyph-kai-8bfe","script":"kai","character":"课","reading":"kè","description":"督促完成指定的工作\n按规定的内容和分量讲授或学习\n⒈学校里教学的科目、进程政治～。数学～。～程表。上～了。\n⒉督促完成工作任务宜严～农桑。〈引〉教授或学习～徒。～读。昼～赋，夜～书，间又～诗。\n⒊旧指规定的赋税，也指征收赋税国～。～以重税。\n⒋机关、学校等单位分设的办事部门出纳～。教务～。\n⒌试验，考核不～不用。\n⒍迷信者的骗术活动，占卜的一种起～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-课"},{"id":"glyph-kai-8c01","script":"kai","character":"谁","reading":"shuí","description":"哪个人或哪些人\n某人\n每个人\n表示疑问。指事物,相当于什么”\n⒈疑问代词。什么人～在说话？\n⒉任何人这件事～都能做。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谁"},{"id":"glyph-kai-8c03","script":"kai","character":"调","reading":"diào","description":"盐或提拔官吏\n征用,提取,征发\n调动\n我是个调虎离山\n①调动；分派～离、～兵谴将。\n②曲调音乐上高低长短配合而成的一组音二黄～、咏叹～。\n③调式；决定整首乐曲取音高低的类别f大～。\n④声调。也指说话、读书、朗诵的腔调。又见tiáo。\n【调号】〈音〉音乐符号。指定乐曲主音高度的符号。五线谱中在g谱号、f谱号或c谱号上加升记号或降记号来标明，标记在各行谱表的最左方。简谱中用1=c或1=g等符号，标\n记在乐曲的左上方。\n【调虎离山】比喻用计谋调动对方离开原来的有利地位，乘机达到自己的目的。\n【调遣】调派；分派。\n【调性】〈音〉调式类别与主音高度本身所具有的特质。如以c音为主音的大调式称c大调；以a音为主音的小调式称a小调。\n⒈配合均匀适当～色。～味。风～雨顺。\n⒊戏弄，挑逗～戏。～唆。～拨。～情。\n⒋顽皮，爱开玩笑～皮。\n①配药。\n②调配，调整，使均匀适当～剂。～剂原料。\n调zhōu 1.朝，早晨。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-调"},{"id":"glyph-kai-8c05","script":"kai","character":"谅","reading":"liàng","description":"固执,坚持己见\n谅解\n⒈原谅，体谅见～。～我此心。\n⒉料想～必。～他不敢。\n⒊诚信～哉斯言。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谅"},{"id":"glyph-kai-8c06","script":"kai","character":"谆","reading":"zhūn","description":"诚恳;忠诚\n谆zhūn恳切。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谆"},{"id":"glyph-kai-8c08","script":"kai","character":"谈","reading":"tán","description":"相处融洽\n⒉言论奇～怪论。高～阔论。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谈"},{"id":"glyph-kai-8c0a","script":"kai","character":"谊","reading":"yì","description":"意义,意思\n友情,友好关系\n谊yì交情，情意友～。深情厚～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谊"},{"id":"glyph-kai-8c0b","script":"kai","character":"谋","reading":"móu","description":"肉食者谋之。\n⒈计划，计策，主意～划。～略。计～。足智多～。\n⒉商议，商量不～而合。\n⒊设法寻求为人民～幸福。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谋"},{"id":"glyph-kai-8c0d","script":"kai","character":"谍","reading":"dié","description":"间谍\n传递的情报\n通牒”。书札\n①秘密刺探军事、政治及经济方面的情报～报。\n②进行谍报活动的人间～。\n【谍报】\n①刺探到的情报。\n②将刺探到的情报交给上级或有关方面。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谍"},{"id":"glyph-kai-8c0e","script":"kai","character":"谎","reading":"huǎng","description":"梦中讲的话\n不公平或欺骗的价格\n哄骗,用假话或手段骗人\n虚假\n⒈骗人，假话～骗。～话。～报。莫撒～。〈引〉商贩要的虚价要～。\n⒉说谎话～称。～说。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谎"},{"id":"glyph-kai-8c10","script":"kai","character":"谐","reading":"xié","description":"言语或行为有趣而引人发笑\n心亲不复异新旧,使脱\n⒈融洽，配合适当～作⊥～。\n⒉滑稽，谈笑随便诙～。～谈。亦庄亦～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谐"},{"id":"glyph-kai-8c13","script":"kai","character":"谓","reading":"wèi","description":"谓唐雎曰。\n不可谓仁。\n不可谓忠。\n不可谓知类。\n评论\n⒈说，告诉可～。愚公～智叟曰。\n⒉叫做，称为，因为～之。称～∥～？\n⒋意义无～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谓"},{"id":"glyph-kai-8c1a","script":"kai","character":"谚","reading":"yàn","description":"通唁”。慰问死者家属\n粗野不恭\n乃逸乃谚,既\n谚yàn谚语，社会上流传的简练、通俗、具有固定性的语言民～。古～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谚"},{"id":"glyph-kai-8c1c","script":"kai","character":"谜","reading":"mí","description":"猜谜儿\n謎谜  mi\n而君子嘲隐,化为谜语。\n没有弄清楚的事物\n谜底\n谜语的答案\n谜团\n谜团\n难解的谜团\n谜语","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谜"},{"id":"glyph-kai-8c22","script":"kai","character":"谢","reading":"xiè","description":"用言辞委婉地推辞拒绝\n⒈感激～ ～你。感～。\n⒉道歉，认错～过。～罪。\n⒊〈古〉告诉多～后世人。\n⒋推辞，辞别～绝。～客。\n⒌衰亡，凋落新陈代～。花～花落。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谢"},{"id":"glyph-kai-8c23","script":"kai","character":"谣","reading":"yáo","description":"流言\n行歌,乐曲\n⒈不用伴奏的韵语、歌词童～。民～。歌～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谣"},{"id":"glyph-kai-8c24","script":"kai","character":"谤","reading":"bàng","description":"诽谤","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谤"},{"id":"glyph-kai-8c26","script":"kai","character":"谦","reading":"qiān","description":"通\"嫌\"。嫌疑\n贵而不为\n谦qiān虚心，不自满～虚。～逊。～让。～恭。～受益。\n谦qiè 1.满足;快意。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谦"},{"id":"glyph-kai-8c28","script":"kai","character":"谨","reading":"jǐn","description":"以谨罔极。\n恭敬\n⒈慎重，小心～慎。～防。～遵法令。\n⒉敬词。〈表〉郑重，恭敬～启。～呈。～具此证。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谨"},{"id":"glyph-kai-8c2c","script":"kai","character":"谬","reading":"miù","description":"⒈错误，与客观事实不符～论。～误。荒～。大～。\n⒉差误差以毫厘，～以千里。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谬"},{"id":"glyph-kai-8c2d","script":"kai","character":"谭","reading":"tán","description":"绵延相及\n宏大,广大\n同谈”。言论\n此老生之常\n⒈同\"谈\"老生常～。\n⒉周代诸侯国名，在今山东省济南市东。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谭"},{"id":"glyph-kai-8c31","script":"kai","character":"谱","reading":"pǔ","description":"符号或文字列记乐歌的音节、声调,以便奏唱的籍录\n⒈记载事物类别、系统等的表册或书籍菜～。年～。家～。\n⒉记录音乐、棋局等符号、图形的样本或书册曲～。乐～。五线～。棋～。画～。\n⒊按歌词作曲～曲。\n⒋大致的准则，把握心中有～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谱"},{"id":"glyph-kai-8c34","script":"kai","character":"谴","reading":"qiǎn","description":"旧时官吏被贬或谪戍\n⒈责备～责。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谴"},{"id":"glyph-kai-8c37","script":"kai","character":"谷","reading":"gǔ","description":"两山之间的水流\n泉出通川为谷\n⒈庄稼和粮食的总称种～。～物。～贵饿农。～贱伤农。\n⒌见yù、lù。榖gǔ榖树，也叫\"构\"或\"楮\"。落叶乔木，花淡绿色，果实红色。树皮纤维可以造纸。\n谷gòu 1.小孩。 2.古代楚语谓乳。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谷"},{"id":"glyph-kai-8c41","script":"kai","character":"豁","reading":"huō","description":"huō：(1)残缺，裂开～口。～子（残缺的口子）。\n(2)舍弃～出性命。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-豁"},{"id":"glyph-kai-8c46","script":"kai","character":"豆","reading":"dòu","description":"dòu：(1)双子叶植物的一科，木本、草本植物都有，如紫檀”、槐树”、黄豆”、绿豆”、红豆”、豌豆”、落花生”等，日常统称豆类植物，亦指这些植物的种子～科。～子。～荚（豆角儿）。～浆。～绿。煮～燃萁。目光如～。\n(2)形状像豆粒的东西土～儿。\n(3)古代盛肉或其他食品的器皿，形状像高脚盘俎～。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-豆"},{"id":"glyph-kai-8c4c","script":"kai","character":"豌","reading":"wān","description":"wān：〔～豆〕ａ．一年生或二年生草本植物，结荚果。嫩荚和种子可食；ｂ．这种植物的种子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-豌"},{"id":"glyph-kai-8c5a","script":"kai","character":"豚","reading":"tún","description":"tún：小猪，亦泛指猪～肩。～蹄。～儿（谦称自己的儿子）。\n〔～鼠〕哺乳动物，亦称荷兰猪”、天竺鼠”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-豚"},{"id":"glyph-kai-8c61","script":"kai","character":"象","reading":"xiàng","description":"xiàng：(1)哺乳动物，是地球上最大的动物，多产在印度、非洲等热带地区，门牙极长，可用于雕刻成器皿或艺术品～牙。～牙宝塔（喻脱离群众和生活的文学家、艺术家的小天地）。\n(2)形状，样子形～。景～。气～。现～。想～。～征。万～更新。～声。～形。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-象"},{"id":"glyph-kai-8c6a","script":"kai","character":"豪","reading":"háo","description":"háo：(1)具有杰出才能的人～杰。英～。文～。自～。\n(2)气魄大，直爽痛快，没有拘束的～放。～爽。～迈。～气。～情。～兴（xìng）。～举。～语。～华。\n(3)强横的，有特殊势力的～强。～门。～族。～绅。巧取～夺。\n(4)古同毫”，极小。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-豪"},{"id":"glyph-kai-8c6b","script":"kai","character":"豫","reading":"yù","description":"yù：(1)欢喜，快乐～附。～游（逸乐嬉游）。不～之色。\n(2)同预”。\n(3)安闲，舒适逸～。\n(4)古同与”，参与。\n(5)中国河南省的别称～剧（亦称河南梆子”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-豫"},{"id":"glyph-kai-8c79","script":"kai","character":"豹","reading":"bào","description":"bào：(1)哺乳动物，能上树，常捕食鹿、羊、猿猴等，毛皮可制衣、褥～头环眼（形容人面目威严凶狠）。未窥全～。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-豹"},{"id":"glyph-kai-8c7a","script":"kai","character":"豺","reading":"chái","description":"chái：哺乳动物，贪食，残暴，常成群侵袭家畜。分布于中国及俄罗斯西伯利亚、印度尼西亚等地（亦称豺狗”）～狼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-豺"},{"id":"glyph-kai-8c8c","script":"kai","character":"貌","reading":"mào","description":"mào：(1)面容面～。容～。～相。以～取人。\n(2)外表的样子礼～。～合神离。道～岸然。\n(3)外观全～。\n(4)古书注解里表示状态、样子，如飞貌”指飞的样子。\n(5)描绘，画像命工～妃于别殿”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-貌"},{"id":"glyph-kai-8d1d","script":"kai","character":"贝","reading":"bèi","description":"牡蛎、蛤或其它软体动物中腹足类和瓣鳃类的统称。体软无节,外束膜一层曰外套膜,能分泌液质,结构成壳,名为介\n贝壳\n古代货币\n①软体动物的总称。特指有介壳的软体动物。如蚌、蛤蜊等。\n②古代用贝壳做的货币。\n③姓。\n【贝雕】用贝壳雕刻或镶嵌成的工艺品。\n【贝尔格莱德】南斯拉夫首都。也是塞尔维亚首府。位于东北部、萨瓦河同多瑙河交汇处。面积182平方公里。是全联邦的重要水、陆、空交通枢纽。\n【贝加尔湖】世界最深的湖泊。位于苏联东西伯利亚南部。平均深730米，最深达1620米。面积3.15万平方公里〓面海拔456米。淡水湖。水生动物种类繁多。\n【贝母】百合科多年生草本。叶条形，花被黄绿色，下垂钟形。鳞茎入药，有祛痰止咳作用。种类多。如四川的川贝母、东北的平贝母、新疆的伊贝母等。\n【贝宁雕塑】贝宁是西非的古国，位于今尼日利亚境内，有过高度的文明史。贝宁雕刻有铜塑和泥塑像。其作风写实而富有装饰性，造型洗练完美，显示出非洲黑人的高度智慧和艺术创造才能。\n【贝希斯顿铭文】波斯帝国国王大流士一世建立的记功石刻。用古波斯文、新埃兰文和巴比伦文3 种楔形文字刻在古都埃克巴坦那西南的贝希斯顿崖石上。是研究古波斯帝国历史的珍贵资料。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贝"},{"id":"glyph-kai-8d1e","script":"kai","character":"贞","reading":"zhēn","description":"假借为正”、为定”。端方正直\n⒈坚定，有节操，有气节忠～。坚～不屈。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贞"},{"id":"glyph-kai-8d1f","script":"kai","character":"负","reading":"fù","description":"⒈输，败，跟\"胜\"相对三胜二～。\n⒉背～粮。～荷。～载。～荆请罪。〈引〉担任～责尽职。～有重任。\n⒊遭受～屈。～轻伤。\n⒋仗恃，依靠～嵎顽抗。～险固守。\n⒌具有久～盛名。\n⒍违背，背弃～约。忘恩～义。\n⒎欠～债。\n⒏小于零的～数。\n⒐相对的两方面之反面，跟\"正\"相对～电。～极。\n【负气】赌气。\n【负疚】自己觉得惭愧不安。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-负"},{"id":"glyph-kai-8d21","script":"kai","character":"贡","reading":"gòng","description":"⒈〈古〉将物品进献给皇帝进～。\n⒉〈古〉进献给皇帝的物品～品。入～。\n⒊封建时代推荐、选举人才给朝廷～举。～生。～士。\n①将力量、知识、财物等献给国家和人民为祖国实现四个现代化，～献出自己的力量。\n②对人民、对人类所做的有益之事为人类作～献。伟大的～献。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贡"},{"id":"glyph-kai-8d22","script":"kai","character":"财","reading":"cái","description":"苟粟多而财有余,\n财 金钱或物资～务、人～两空。\n【财帛】钱财。\n【财阀】以家族为中心、带有一定封建性的金融资本集团。以第二次世界大战前日本的最为典型。\n【财团】金融资本的组织形式。金融寡头所控制的大银行和大企业结合而成的垄断资本集团。\n【财政】国家对资财的收入与支出施行的管理～包干。\n【财政赤字】国家财政年度的支出超过收入的差额。这种差额，会计上习惯用红字表示，故称。又称预算赤字。\n【财政寡头】见【金融寡头】。\n【财政资本】见【金融资本】。\n财cái 1.金钱﹑物资的总称。 2.通\"材\"。原料;材料。 3.通\"才\"。资质，才能。 4.通\"裁\"。裁制;节制;裁断。 5.通\"纔\"。仅仅。 6.通\"纔\"。始，刚才。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-财"},{"id":"glyph-kai-8d23","script":"kai","character":"责","reading":"zé","description":"责一头。\n以塞官责。\n责备\n⒈分内应做的事～任。负～。尽职尽～。人人有～。\n⒊质问，诘问～问。\n⒋指摘斥～。谴～。\n⒌惩罚～罚。鞭～。杖～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-责"},{"id":"glyph-kai-8d24","script":"kai","character":"贤","reading":"xián","description":"有德行;多才能\n对人的敬称\n分明是如贤所教,但是小生自小坐书斋,不谙其他生活。╠\n⒈有道德、有才能的，也指德才兼备的人～明。选～与能。用人唯～。\n⒉胜过，甚于～于。\n⒊敬词。用于平辈或晚辈～妻。～甥。\n⒋〈古〉劳苦我从事独～。\n贤xiàn 1.车毂一端的大孔。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贤"},{"id":"glyph-kai-8d25","script":"kai","character":"败","reading":"bài","description":"①失败残兵～将、成～在此一举。\n②打败大～敌军。\n④消除；解除～火。\n⑤破旧；腐烂；凋谢#草&开不#的鲜花。\n【败北】打败仗。\n【败笔】指写字写得不好的一笔。也指绘画中画得不好的部分或作文中写得不好～的词句。\n【败绩】指战争、事业等方面的失败。\n【败兴】正高兴时因遇到不希望发生的事而情绪低落；扫兴郊游时天下起了雨，真～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-败"},{"id":"glyph-kai-8d26","script":"kai","character":"账","reading":"zhàng","description":"账簿\n⒈钱财出入的记载记～。现金日记～。\n⒉登记账目、户籍的本子或单子～簿。一本～。户籍～。一篇～单。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-账"},{"id":"glyph-kai-8d27","script":"kai","character":"货","reading":"huò","description":"财物,金钱珠玉布帛的总称\n患货之不足。\n⒈钱～币。通～。\n⒊商品～物充足。百～齐全。\n⒋卖～出。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-货"},{"id":"glyph-kai-8d28","script":"kai","character":"质","reading":"zhì","description":"援疑质理\n⒉朴实～朴。\n⒊抵押，抵押品典～。人～。\n⒋问，责问～疑。～问。\n⒌评判，核对而欲～天之有无。对～。\n①物理学上指物体所含物质的量。常用单位为克、公斤等。\n②指产品或工作的优劣程度产品～量。教学～量。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-质"},{"id":"glyph-kai-8d29","script":"kai","character":"贩","reading":"fàn","description":"古国名\n买货出售\n也单指买进货物\n比喻叛卖\n⒈指买货或买后再出卖～了一批货回来。～卖。\n⒉做买卖的行商或小商人小商～。摆摊～。鱼～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贩"},{"id":"glyph-kai-8d2a","script":"kai","character":"贪","reading":"tān","description":"贪婪。多欲而不知满足\n贪tān图财。原指贪财，后多指贪污。不知足的求取严惩～官。～赃枉法。～耍。～婪。～便宜。～心不足。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贪"},{"id":"glyph-kai-8d2b","script":"kai","character":"贫","reading":"pín","description":"⒊言语噜苏，令人讨厌他耍～嘴。她那张嘴太～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贫"},{"id":"glyph-kai-8d2c","script":"kai","character":"贬","reading":"biǎn","description":"降级\n特指降职并外放;贬谪\n其后\n②指出缺点，给予不好的评价，与'褒'相对有褒有～。\n【贬斥】\n①降低官级。\n②贬低并压制、排斥。\n【贬黜】降低或罢免官职。\n【贬低】有意降低对人或事物的评价。\n【贬义】言辞或字句里含有不赞成或坏的意思～词。\n【贬义词】含有厌恶、贬斥等感情色彩的词。\n【贬抑】贬低并压制。\n【贬责】指出过失、加以批评；责备横加～。\n【贬谪】封建时代指官吏降职，被派到边远地方做官。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贬"},{"id":"glyph-kai-8d2d","script":"kai","character":"购","reading":"gòu","description":"原指用重金收买,后泛指买","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-购"},{"id":"glyph-kai-8d2e","script":"kai","character":"贮","reading":"zhù","description":"以广贮江宁、杭州、苏州之病梅\n贮zhù 1.储存;收藏。 2.指储存的财货。 3.盛，把东西放在器具里。 4.停放，安置。 5.唐时图籍副本之一。 6.通\"伫\"。等待。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贮"},{"id":"glyph-kai-8d2f","script":"kai","character":"贯","reading":"guàn","description":"旧时用绳索穿钱,每一千文为一贯\n事情,事例\n⒉穿，穿连～穿。～串。连～。〈引〉通，连通～通。学～古今。融会～通。\n⒊原籍，出生地籍～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贯"},{"id":"glyph-kai-8d30","script":"kai","character":"贰","reading":"èr","description":"二的大写\n① '二'的大写。\n②变节；背叛～臣。\n【贰臣】封建时代指在前一朝代做了官，投降后一朝代又做官的人。\n【贰心】见【二心】。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贰"},{"id":"glyph-kai-8d31","script":"kai","character":"贱","reading":"jiàn","description":"地位低下,人格卑鄙\n鄙贱之人。\n其辱\n⒉地位低下，跟\"高贵\"相对卑～。贫～。\n⒊谦词～姓。～恙。\n⒋鄙视，轻视贵五谷而～金玉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贱"},{"id":"glyph-kai-8d34","script":"kai","character":"贴","reading":"tiē","description":"贴补。补偿,补益\n粘附;附着\n⒈粘附粘～。～年画。～对联。\n⒉挨近，紧靠～着河边游。～身汗衫。\n⒊补助～补。粮～。\n⒋恰当，适合，妥当～切。妥～。\n⒌依附，顺从服服～ ～。\n⒍量词。膏药一张 叫一～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贴"},{"id":"glyph-kai-8d35","script":"kai","character":"贵","reading":"guì","description":"社会地位高\n一曰爵以\n⒈价钱高，跟\"贱\"相对米～。油～。〈引〉珍贵，宝贵最～者，人才也。\n⒉地位高或权势大，也指这类的人或集团显～。权～。达官～族。\n⒊重视，崇尚兵～神速。不～义，而～法。\n⒋敬词～姓？～宾。～公司。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贵"},{"id":"glyph-kai-8d37","script":"kai","character":"贷","reading":"dài","description":"借出钱财\n借入\n①借入或借出～款。\n②所贷的款农～。\n③推卸责无旁～。\n④宽恕严惩不～。\n【贷学金制度】高等院校给家庭经济困难的学生发放无息贷款，以保障他们正常的学习和生活的制度。\n贷tè 1.通\"忒\"。差错。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贷"},{"id":"glyph-kai-8d38","script":"kai","character":"贸","reading":"mào","description":"改变\n古今一\n⒈交易，交换财物～易。抱布～丝。\n⒉轻率，冒冒失失～然前去。～ ～然来。\n贸móu 1.目眩。参见\"贸贸\"。 2.昏昧，昏庸。 3.通\"侔\"。等齐。 4.通\"牟\"。谋取。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贸"},{"id":"glyph-kai-8d39","script":"kai","character":"费","reading":"fèi","description":"耗损\n⒈消耗，花掉～尽心机。花～太大。～劲。～时间。莫浪～。\n⒉费用，为某种需要所使用的款项军～。学～。旅～。电～。\n【费解】不好懂他说的这句话太～解。\n费fú 1.违背，不顺利。\n费bì 1.古地名。春秋鲁邑，在今山东省费县西北。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-费"},{"id":"glyph-kai-8d3a","script":"kai","character":"贺","reading":"hè","description":"奉送礼物表示庆祝\n是以贺。\n何贺之有。\n嘉奖;犒劳\n赞许;附和\n贺hè庆祝，祝颂，道喜庆～。祝～。恭～。～电。～新年。～功酒。～喜宴。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贺"},{"id":"glyph-kai-8d3b","script":"kai","character":"贻","reading":"yí","description":"美人之贻。\n遗留\n⒈赠给，送给～人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贻"},{"id":"glyph-kai-8d3c","script":"kai","character":"贼","reading":"zéi","description":"⒈匪盗，偷东西的人盗～。窃～。\n⒉严重桅国家和人民的坏人乱臣～子。卖国～。\n⒊伤害戕～。\n⒋邪的，不正派～眉～眼。～头～脑。\n⒌对敌人的蔑称已破～。\n⒍〈方〉狡猾老鼠太～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贼"},{"id":"glyph-kai-8d3e","script":"kai","character":"贾","reading":"jiǎ","description":"坐卖。泛指卖\n⒈〈古〉商人富商大～。又特指坐商。\n⒉做买卖善～。\n⒋求取～好。〈引〉招引，招惹～祸。\n⒌见jiǎ。\n⒈姓。\n⒉〈古〉通\"价\"。\n⒊见gǔ。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贾"},{"id":"glyph-kai-8d3f","script":"kai","character":"贿","reading":"huì","description":"贿赂的财物\n赠送财物\n孟献子聘于周,王以为有礼\n⒈〈古〉财物货～。\n⒊用财物买通别人或指买通别人的财物被迫行～。索～受～，罪行累累。勤政廉洁，杜绝～赂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贿"},{"id":"glyph-kai-8d41","script":"kai","character":"赁","reading":"lìn","description":"租用、租借\n工钱,给受雇人的报酬\n⒈租，租借租～。出～。～房。\n⒉给人当雇工～佣。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赁"},{"id":"glyph-kai-8d42","script":"kai","character":"赂","reading":"lù","description":"行贿,用钱、物买通别人\n⒈〈古〉指赠送财物。\n⒉财物。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赂"},{"id":"glyph-kai-8d43","script":"kai","character":"赃","reading":"zāng","description":"贪污;行贿","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赃"},{"id":"glyph-kai-8d44","script":"kai","character":"资","reading":"zī","description":"⒊供给，凭借～助。仅～参考。可～借鉴。\n⒋条件，威望～格。～望。\n①用于发展国民经济的物资或货币。\n②本钱。\n资zì 1.逞情;放纵。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-资"},{"id":"glyph-kai-8d4b","script":"kai","character":"赋","reading":"fù","description":"缴纳赋税\n给予;授予\n⒉授予，给予～于。\n⒋念诗或作诗临清流而～诗。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赋"},{"id":"glyph-kai-8d4c","script":"kai","character":"赌","reading":"dǔ","description":"泛指比胜负;争输赢\n①赌博。一种用财物作注争输赢的恶习。\n②泛指争输赢打～。\n【赌咒】发誓。\n【赌注】赌博时所押的钱财。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赌"},{"id":"glyph-kai-8d4e","script":"kai","character":"赎","reading":"shú","description":"用财物脱罪或抵免过失\n⒈用财物换回人或抵押品～回。～当。\n⒉弥补，抵偿立功～罪。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赎"},{"id":"glyph-kai-8d4f","script":"kai","character":"赏","reading":"shǎng","description":"玩赏;欣赏\n奇文共欣\n⒈赐，奖，给予～赐。奖～。～给。\n⒉奖赐的物品有～。受～。领～。\n⒊赞扬赞～。\n⒋喜爱，喜欢，领略趣味～花。～月。欣～。玩～。鉴～。观～。\n⒌敬词～光。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赏"},{"id":"glyph-kai-8d50","script":"kai","character":"赐","reading":"cì","description":"给予;上给予下\n请给\n①赐予。～敬辞。指所受的礼物辱承厚～，受之有愧。\n【赐教】敬辞。给予指教承蒙～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赐"},{"id":"glyph-kai-8d54","script":"kai","character":"赔","reading":"péi","description":"陪嫁\n亏蚀;耗损\n向人道歉或认错\n⒉亏，蚀～钱。～本。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赔"},{"id":"glyph-kai-8d56","script":"kai","character":"赖","reading":"lài","description":"依靠;依赖;依恃、凭藉\n赖子存之。\n⒈倚靠，仗持依～。办好这件事，有～大家同心协力。\n⒉不承认～债。抵～。证据确凿，～是～不掉的。\n⒊诬陷，反过来怪人诬～。自己错了，别～他人。\n⒋怪罪，责备学习成绩差，只能～自己努力不够。\n⒌差，劣，坏这种电视机的质量不～。\n⒍停在某地，不愿离开～在家里。\n⒎［无赖］\n①生活无依无靠。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赖"},{"id":"glyph-kai-8d58","script":"kai","character":"赘","reading":"zhuì","description":"聚会\n通缀”。连缀,附着\n⒉男子就婚女家～婿。入～。招～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赘"},{"id":"glyph-kai-8d5a","script":"kai","character":"赚","reading":"zuàn；zhuan","description":"赢得;获得\n出错误\n⒈诳骗～得英雄咀头。\n⒈得利，挣得，占便宜～钱。有～头。外出参观还～，到处招待，～了不少，这是歪风邪气。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赚"},{"id":"glyph-kai-8d5b","script":"kai","character":"赛","reading":"sài","description":"比试\n⒈比较好坏、强弱、胜负比～。排球～。拔河～。\n⒉胜似，比得上一年～一年。能～过他。\n⒊旧时一种迷信活动，所谓\"酬报神灵\"而举行的祭典～神。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赛"},{"id":"glyph-kai-8d5e","script":"kai","character":"赞","reading":"zàn","description":"导引\n辅佐,佐助\n赞帷幄之谋\n⒈辅佐，帮助～助。\n⒉称颂，夸奖～美。～扬。～许。称～。\n①同意。\n②支持，助人成功。\n①婚、丧、庆典、祭祀等仪式进行时，在旁宣诵行礼项目。\n②赞礼的人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赞"},{"id":"glyph-kai-8d60","script":"kai","character":"赠","reading":"zèng","description":"赠zèng送，无代价地送东西给别人～送。～阅。～言。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赠"},{"id":"glyph-kai-8d61","script":"kai","character":"赡","reading":"shàn","description":"周济;帮助\n充满\n足;充足\n⒈富足，充足丰～。\n⒉供给～养。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赡"},{"id":"glyph-kai-8d62","script":"kai","character":"赢","reading":"yíng","description":"宽缓;松懈\n大夫君\n⒈获利，利润～利。～余。\n⒉获得，得到～得。\n⒊胜，获胜打～了。\n⒋背，担～粮。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赢"},{"id":"glyph-kai-8d63","script":"kai","character":"赣","reading":"gàn","description":"赣江,在江西省\n江西省的别称\n⒈江西省的简称。\n⒉赣江，在江西省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赣"},{"id":"glyph-kai-8d64","script":"kai","character":"赤","reading":"chì","description":"chì：(1)红色，比朱色稍暗的颜色～血。～字。\n(2)真诚，忠诚～诚（极其真诚）。～忱。～子（纯洁无暇的初生婴儿，古代亦指百姓）。～胆忠心。\n(3)空无所有～手空拳。～地千里。\n(4)裸露～脚（光脚）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赤"},{"id":"glyph-kai-8d66","script":"kai","character":"赦","reading":"shè","description":"shè：免除和减轻刑罚～书。～令。～免。～恕。大～。特～。十恶不～。罪在不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赦"},{"id":"glyph-kai-8d6b","script":"kai","character":"赫","reading":"hè","description":"hè：(1)明显，显著，盛大显～。喧～。～奕。～烜。\n(2)发怒～咤。～怒。～然。\n(3)红如火烧，泛指红色～如渥赭”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赫"},{"id":"glyph-kai-8d70","script":"kai","character":"走","reading":"zǒu","description":"zǒu：(1)行～路。～步。\n(2)往来～亲戚。\n(3)移动～向（延伸的方向）。～笔（很快地写）。钟表不～了。\n(4)往来运送～信。～私。\n(5)离去～开。刚～。出～。\n(6)经过～账。～内线。～后门。\n(7)透漏出去，超越范围～气（漏气）。\n(8)失去原样～形。～样。\n(9)古代指奔跑～马。不胫而～。\n(10)仆人，我”的谦辞牛马～（当牛作马的仆人，如太史公～～～。”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-走"},{"id":"glyph-kai-8d74","script":"kai","character":"赴","reading":"fù","description":"fù：(1)往，去～京。～会。～任。～约。～宴。\n(2)投入（某种境地），参加（某种行列）～战。～敌（加入对敌作战）。～难（nàn）。～义。\n(3)古同讣”，讣告。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赴"},{"id":"glyph-kai-8d75","script":"kai","character":"赵","reading":"zhào","description":"字亦作踴”\n古国名\n周穆王封造父于赵,故址在今山西省赵城县西南\n战国七雄之一。在今山西北部、河北西部和南部一带\n赵王于是遂遣。\n赵diào 1.锄地铲草。 2.通\"掉\"。参见\"赵缭\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赵"},{"id":"glyph-kai-8d76","script":"kai","character":"赶","reading":"gǎn","description":"追赶,从后面追上\n急赴\n驱逐\n⒈追你追我～。迎头～上。～超世界先进水平。〈引〉加快，从速，及时达到～快。～紧。～工。～上这班车。\n⒉驱使，驾驭，驱逐～马儿。～牛车。把外籍罪犯～出国门。\n赶qián 1.兽类翘尾奔跑。 2.引申为翘起尾巴或屁股。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赶"},{"id":"glyph-kai-8d77","script":"kai","character":"起","reading":"qǐ","description":"qǐ：(1)由躺而坐或由坐而立等～床。～立。～居。～夜。\n(2)离开原来的位置～身。～运。～跑。\n(3)开始～始。～码（最低限度，最低的）。～步。～初。～讫。～源。\n(4)拔出，取出～锚。～获。\n(5)领取（凭证）～护照。\n(6)由下向上，由小往大里涨～伏。～劲。～色。\n(7)发生，产生，发动，提出～风。～腻。～敬。～疑。～义。～诉。\n(8)长出～痱子。\n(9)拟定～草。\n(10)建造，建立～房子。白手～家。\n(11)群，组，批一～（一块儿）。\n(12)量词，指件，宗一～案件。\n(13)自，从～小儿就淘气。\n(14)用在动词后，表示动作的趋向想～。掀～。兴（xīng）～。\n(15)用在动词后，与来”连用，表示动作开始唱～来。\n(16)用在动词后，常与不”或得”连用，表示胜任；亦表示达到某一种标准看不～。经得～检验。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-起"},{"id":"glyph-kai-8d81","script":"kai","character":"趁","reading":"chèn","description":"chèn：(1)利用时间、机会～早。～机。～势。～火打劫（趁人家发生火灾时去抢劫，喻在别人危难时乘机去捞好处）。～热打铁。\n(2)搭乘～车。～船。\n(3)逐，追赶花底山蜂远～人”。\n(4)往，赴～墟（赶集）。～熟（逃荒到丰收之处）。\n(5)富有～钱。～几身衣服。\n(6)古同称”，适合。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-趁"},{"id":"glyph-kai-8d85","script":"kai","character":"超","reading":"chāo","description":"chāo：(1)越过，高出～越。高～。～出。～额。～龄。～等。～载。～重。～支。\n(2)跳上，跨过挟泰山以～北海”。\n(3)在一定范围以外～自然。～音速。～导现象。\n(4)遥远～遥。～忽。\n(5)怅惘的样子武侯～然不对”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-超"},{"id":"glyph-kai-8d8a","script":"kai","character":"越","reading":"yuè","description":"yuè：(1)度过，超出～过。～冬。～级。～轨。～权。～境。～位。～狱。～俎代庖。\n(2)声音、情感扬起，昂扬激～。声音清～。\n(3)表示程度加深～发（更加）。～加。～快～好。\n(4)消散精神劳则～”。\n(5)失坠，坠落陨～。射其左。～于车下”。\n(6)中国古民族名百～（亦作百粤”）。\n(7)中国周代诸侯国名◇用作浙江省东部的别称～剧。～凫楚乙（乙”，燕子。喻对于同一事物，由于自身条件的局限而作出不同的判断）。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-越"},{"id":"glyph-kai-8d8b","script":"kai","character":"趋","reading":"qū","description":"步,行走\n⒈快走～走。～而迎之。\n⒉向往，奔向，向着某方面发展～向。～势。～之若鹜。～于一致。\n⒊〈古〉通\"促\"。催促。\n趋cù 1.敦促;促使。 2.催迫;催促。 3.急促;迫切。 4.赶快;立即。 5.矮，短促。\n趋qù 1.志向;意趣。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-趋"},{"id":"glyph-kai-8d9f","script":"kai","character":"趟","reading":"tàng；tāng","description":"tàng：(1)来往的次数走一～。\n(2)行（háng），行列两～桌子。\n〔～马〕戏曲中表演骑着马走或跑的一套程式动作。\n〔赶～儿〕ａ．赶得上，来得及，如明天早上再走也～～～”；ｂ．凑热闹，如桃树、杏树、梨树，你不让我，我不让你，都开满了花～～～”。\ntāng：(1)从浅水里走过去～水过河。\n(2)用犁、锄等把土翻开，除去杂草并给苗培土～地。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-趟"},{"id":"glyph-kai-8da3","script":"kai","character":"趣","reading":"qù；cù","description":"qù：(1)趋向志～。意～。旨～。\n(2)兴味，使人感到愉快兴～。乐～。情～。雅～。妙～。相映成～。～事。～味。\ncù：古同促”，催促；急促。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-趣"},{"id":"glyph-kai-8db3","script":"kai","character":"足","reading":"zú","description":"zú：(1)脚～下（对对方的敬称）。～迹。～球。～坛。失～。高～（敬辞，称别人的学生）。举～轻重。画蛇添～。\n(2)器物下部的支撑部分鼎～。碗～。\n(3)充分，够量～月。～见。～智多谋。\n(4)完全～以。～色。\n(5)值得，够得上不～为凭。微不～道。\n(6)增益以昼～夜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-足"},{"id":"glyph-kai-8db4","script":"kai","character":"趴","reading":"pā","description":"pā：(1)肚子向下卧倒～下。～虎儿（身体向前跌倒的姿势）。～窝（ａ．母鸡趴在窝里孵小鸡；ｂ．母畜生幼畜前趴在地上不动；ｃ．身体垮了；ｄ．机器和机动车等发生故障，不能开动）。\n(2)身体向前靠在东西上～在桌子上。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-趴"},{"id":"glyph-kai-8dbe","script":"kai","character":"趾","reading":"zhǐ","description":"zhǐ：(1)脚～高气扬。\n(2)脚指头～骨。～甲。\n(3)踪迹庶追芳～”。\n(4)古同址”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-趾"},{"id":"glyph-kai-8dc3","script":"kai","character":"跃","reading":"yuè","description":"若将跃舞。\n上竖;上举\n⒈跳跳～。飞～。\n①跳着前进。\n②飞快地前进。\n跃tì 1.见\"跃跃\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跃"},{"id":"glyph-kai-8dcb","script":"kai","character":"跋","reading":"bá","description":"bá：(1)翻山越岭～涉。\n(2)踩，践踏～前踬后（喻进退两难）。\n(3)文章或书籍正文后面的短文，说明写作经过、资料来源等与成书有关的情况～文。～语。序～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跋"},{"id":"glyph-kai-8dcc","script":"kai","character":"跌","reading":"diē","description":"diē：(1)摔～跤。～倒。\n(2)下降，低落～落。～销。水位下～。\n(3)顿足，跺～足大叹。\n(4)疾行～蹄而行千里。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跌"},{"id":"glyph-kai-8dd1","script":"kai","character":"跑","reading":"pǎo；páo","description":"pǎo：(1)奔，两脚交互向前迅速跃进～步。奔～。赛～。\n(2)很快地移动～动。\n(3)逃～出笼子。\n(4)漏泄～电。～气。\n(5)为某种事物奔走～买卖。～外的。～堂。～码头。～单帮。\npáo：走兽用脚刨地～糟（牲口用蹄糟根）。虎～泉（在中国浙江省杭州市）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跑"},{"id":"glyph-kai-8ddb","script":"kai","character":"跛","reading":"bǒ","description":"bǒ：腿或脚有病，走路时身体不平衡，瘸～脚。～子。～行。～鳖千里（喻本身条件再差，只要不懈努力，终能获得成功）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跛"},{"id":"glyph-kai-8ddd","script":"kai","character":"距","reading":"jù；jv","description":"jù：(1)相隔的空间和时间相～数里。～离。行（háng）～。株～。差（chā）～。\n(2)雄鸡爪子后面突出像脚趾的部分。\n(3)古同拒”，抵抗。\n(4)古同巨”，大。\n(5)古同讵”，岂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-距"},{"id":"glyph-kai-8ddf","script":"kai","character":"跟","reading":"gēn","description":"gēn：(1)脚的后部，踵脚后～。\n(2)鞋袜的后部高～鞋。袜后～儿。\n(3)随在后面，紧接着～随。～踪。\n(4)赶，及～不上班。\n(5)和，同我～他在一起工作。\n(6)对，向我已经～他说了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跟"},{"id":"glyph-kai-8de4","script":"kai","character":"跤","reading":"jiāo","description":"jiāo：身体摔倒摔～。跌了一～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跤"},{"id":"glyph-kai-8de8","script":"kai","character":"跨","reading":"kuà","description":"kuà：(1)抬腿向前或向旁移动越过，迈过～进。～入。～度。\n(2)骑，两脚分在器物的两边坐着或立着～马。小孩～着门槛。\n(3)超过时间或地区之间的界限～越。～年度。～国公司。\n(4)附在旁边～院。\n(5)古同胯”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跨"},{"id":"glyph-kai-8dea","script":"kai","character":"跪","reading":"guì","description":"guì：(1)两膝着地，腰和股都伸直～拜。～叩。\n(2)足蟹六～而二螯”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跪"},{"id":"glyph-kai-8def","script":"kai","character":"路","reading":"lù","description":"lù：(1)道，往来通行的地方道～。公～。水～。陆～。～途。～程。～人（行路的人，喻不相干的人）。狭～相逢。\n(2)思想或行动的方向、途径思～。生～。出～。～子。～数（shù）。\n(3)方面，地区外～货。各～人马。\n(4)种类一～货色。\n(5)大，正厥声载～”。～门（宫室最内的正门）。～车（古代帝王及诸侯贵族所乘的车）。～舆（古代君主所乘的车）。～寝（古代君主处理政事的宫室）。\n(6)车筚～。乘～。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-路"},{"id":"glyph-kai-8df3","script":"kai","character":"跳","reading":"tiào；táo","description":"tiào：(1)两脚离地全身向上或向前的动作～跃。～水。～荡。～踧。～高。～远。～舞。弹（tán）～。暴～如雷。～梁小丑（指上蹿下跳，兴风作浪的微不足道的坏人）。\n(2)越过～班。～棋。～槽。\n(3)一起一伏地动心～。眼～。心惊肉～。\ntáo：古同逃”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跳"},{"id":"glyph-kai-8df5","script":"kai","character":"践","reading":"jiàn","description":"履行;实现\n⒈踩，踏～踏。马～。\n⒉实行，履行～言。～约。实～。\n⒊到，临重～故里。\n⒋〈古〉通\"翦\"。灭掉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-践"},{"id":"glyph-kai-8df7","script":"kai","character":"跷","reading":"qiāo","description":"竖起\n踮起脚后跟\n用同","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跷"},{"id":"glyph-kai-8dfa","script":"kai","character":"跺","reading":"duò","description":"duò：提起脚来用力踏地～脚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跺"},{"id":"glyph-kai-8e0a","script":"kai","character":"踊","reading":"yǒng","description":"登,登上\n百姓疲于土木之功,金\n⒈跳跃。\n⒉登上，上涨腾～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-踊"},{"id":"glyph-kai-8e0f","script":"kai","character":"踏","reading":"tà","description":"tà：(1)用脚踩～步。～板。～青（春天到郊外散步。亦称踏春”）。～雪。～月。践～。糟～。脚～实地。\n(2)亲自到现场去～看。～勘。～查。～访。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-踏"},{"id":"glyph-kai-8e22","script":"kai","character":"踢","reading":"tī","description":"tī：用脚触击～毽子。一脚～开。～蹬。～踏。～皮球（ａ．抬脚触击皮球；ｂ．喻互相推委，来回扯皮的官僚主义作风）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-踢"},{"id":"glyph-kai-8e29","script":"kai","character":"踩","reading":"cǎi","description":"cǎi：(1)用脚登在上面，踏～了一脚泥。～高跷。～水（一种直立水中的泳姿）。～踏。～墒（在播种的地方踩实土壤以保墒）。\n(2)指追踪盗匪或追查案件～访。～捕。～案。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-踩"},{"id":"glyph-kai-8e2a","script":"kai","character":"踪","reading":"zōng","description":"zōng：人或动物走过留下的脚印～影。～迹。追～。失～。跟～。无影无～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-踪"},{"id":"glyph-kai-8e31","script":"kai","character":"踱","reading":"duó","description":"duó：慢慢地走～方步。～来～去。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-踱"},{"id":"glyph-kai-8e42","script":"kai","character":"蹂","reading":"róu","description":"róu：践踏～踏。～躏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹂"},{"id":"glyph-kai-8e44","script":"kai","character":"蹄","reading":"tí","description":"tí：马、牛、猪等生在趾端的保护物，亦指有角质保护物的脚～子。～筋。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹄"},{"id":"glyph-kai-8e48","script":"kai","character":"蹈","reading":"dǎo","description":"dǎo：(1)践踏，踩～袭（走别人走过的老路，沿用前人旧例）。～节（信守节操）。～海（跳到海里自杀）。赴汤～火。循规～矩。\n(2)跳动舞～。手舞足～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹈"},{"id":"glyph-kai-8e4b","script":"kai","character":"蹋","reading":"tà","description":"tà：(1)踏舞辄数十人相随，～地为节。”\n(2)踢穿域～鞠”（鞠”，古代的一种皮球）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹋"},{"id":"glyph-kai-8e66","script":"kai","character":"蹦","reading":"bèng","description":"bèng：两脚并着跳～跳。～高。欢～乱跳（亦称活蹦乱跳”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹦"},{"id":"glyph-kai-8e6c","script":"kai","character":"蹬","reading":"dēng","description":"dēng：同登”②。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹬"},{"id":"glyph-kai-8e6d","script":"kai","character":"蹭","reading":"cèng","description":"cèng：(1)磨，擦～脱一层皮。\n(2)由擦过而沾上～一身灰。\n(3)拖延磨（mó）～。～时间。\n(4)一步一步缓慢地移动慢慢往前～。\n(5)指白占便宜坐～车。\n〔～蹬（dèng）〕ａ．失势难进的样子，如或乃～～穷波，陆死盐田”；ｂ．喻失意、潦倒，如岂知～～不称意，八年梁益雕朱颜”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹭"},{"id":"glyph-kai-8e72","script":"kai","character":"蹲","reading":"dūn","description":"dūn：(1)两腿尽量弯曲，像坐的样子，但臀部不着地～下。～伏。～踞。～腿。\n(2)喻呆着或闲居～膘。～窝。～班房（坐牢）。\n〔～苗〕在一定时期内控制施肥和灌水，进行中耕和镇压，使幼苗根部下扎，生长健壮，防止多余茎叶生长。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹲"},{"id":"glyph-kai-8e81","script":"kai","character":"躁","reading":"zào","description":"zào：性急，不冷静～动。～进。～狂（浮躁轻狂）。急～。浮～。骄～。烦～。性情～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-躁"},{"id":"glyph-kai-8e8f","script":"kai","character":"躏","reading":"lìn","description":"欺压;伤害","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-躏"},{"id":"glyph-kai-8eab","script":"kai","character":"身","reading":"shēn","description":"shēn：(1)人、动物的躯体，物体的主要部分～躯。人～。～材。～段。船～。树～。\n(2)指人的生命或一生～世。献～。\n(3)亲自，本人自～。亲～。～教。～体力行。\n(4)统指人的地位、品德出～。～分（fèn）。～败名裂。\n(5)孕，娠～孕。\n(6)量词，指整套衣服做了一～儿新衣服。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-身"},{"id":"glyph-kai-8eac","script":"kai","character":"躬","reading":"gōng","description":"gōng：(1)身体。\n(2)自身，亲自反～自问。～行实践。事必～亲。\n(3)弯曲身体鞠～。～身下拜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-躬"},{"id":"glyph-kai-8eaf","script":"kai","character":"躯","reading":"qū","description":"身孕\n躯口”的省称。宋元时代女真族和蒙古族称被俘获并强迫服劳役的汉族人为躯口”\n指生命","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-躯"},{"id":"glyph-kai-8eb2","script":"kai","character":"躲","reading":"duǒ","description":"duǒ：隐藏；退让～藏。～避。～让。～难（nàn）。～车。～开。～闪。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-躲"},{"id":"glyph-kai-8eba","script":"kai","character":"躺","reading":"tǎng","description":"tǎng：身体（亦指器具、车辆）横倒～在床上。～椅。～柜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-躺"},{"id":"glyph-kai-8f66","script":"kai","character":"车","reading":"chē","description":"①陆地上安设轮子的运输工具汽～、马～。\n②利用轮轴旋转的工具水～、吊～。\n③机器～床、～间。\n④用车床切削东西～圆。\n⑤用水车取水～水。\n⑥姓。又见jū。\n【车床】一种常用的金属切削机床。主要用来做内圆、外圆和螺纹加工。又叫旋床。\n【车技】一种杂技节目。表演者利用特制的单轮车、双轮车作载人运行、翻车过桌或在特制的高架上作'定车'等各种表演动作。\n【车厘子】〈港台〉樱桃。英语音译词。\n【车裂】中国古代一种残酷的死刑。将人头和四肢分别绑在五辆车上，以马架车，同时分驰，撕裂肢体。俗称五马分尸。\n【车水马龙】车像流水，马像游龙。形容车马来往不绝、繁华热闹的景象。\n【车载斗量】用车装，用斗量。形容数量非常多。多用来表示不足为奇。\n【车辙】车子经过路面时轧出的痕迹。\n⒈象旗中的一种棋子。\n⒉见chē。\n⒈有轮子的陆上交通工具马～。汽～。轿～。乘用～。火～。\n⒉利用轮轴转动的某些器具水～。纺纱～。滑轮～。〈引〉机器试～。开～。\n⒊旋床～床。\n⒋使用旋床～光。～圆。\n⒌使用水车取水～水。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-车"},{"id":"glyph-kai-8f67","script":"kai","character":"轧","reading":"zhá；ga","description":"挤入;拥挤\n结交\n核查\n排挤,倾轧\n⒈〈方〉\n①挤，拥挤不要～。\n②结交～朋友。\n③核算，查对～清帐目。\n⒉见yà、zhá。\n⒈排挤，碾压倾～。～棉花。～马路。\n⒈压～辊。～钢机。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-轧"},{"id":"glyph-kai-8f68","script":"kai","character":"轨","reading":"guǐ","description":"车轮的痕迹,车辙\n法则、法度\n⒈车子两轮之间的距离车同～。〈喻〉车轮的痕迹城门之～。\n⒉轨道，一定的线路五星循～而行。有～电车。特指铺设轨道的钢铁条铺铁～。架钢～。〈喻〉法度，规则，办法，秩序等纳入正～。制止越～行为。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-轨"},{"id":"glyph-kai-8f69","script":"kai","character":"轩","reading":"xuān","description":"文轩之与敝舆。\n⒈〈古〉一种有帷幕的车，泛指车子乘～。\n⒉有窗槛的长廊或小屋西～。\n轩xiàn 1.大的肉片。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-轩"},{"id":"glyph-kai-8f6c","script":"kai","character":"转","reading":"zhuǎn","description":"回还,转动\n⒈旋动，改变方向、位置或情势等～动。～身。～移。～变。～败为胜。\n⒉不是直接的，中间要经过别的人或地方～告。～运。请～交。～手买卖。\n⒈旋，绕，绕着某点或某物移动旋～。打～。～圈子。车轮飞～。\n⒉量词。绕一圈叫绕\"一转\"。\n转zhuǎi 1.见\"转文\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-转"},{"id":"glyph-kai-8f6e","script":"kai","character":"轮","reading":"lún","description":"引申为车子\n凡平圆形像车轮似的东西\n未央前殿月轮\n⒈安在车上、机器上，能旋转并促使车、机器动作的东西车～子。三～车。齿～儿。偏心～。\n⒊依照次序转～流。～班。第二～。该～到你了。\n①图形或物体的外围。\n②事物的概况。\n轮lún 1.车轮。 2.指车牙。 3.指车毂。 4.代指车。 5.收卷钓线的转轮。 6.古代制作瓦瓶的圆形木模。 7.古代的一种兵器。 8.制作车轮的工匠。 9.树的横枝\n。 10.指月亮。 11.兼指太阳。 12.指人的头与四肢。 13.轮船的省称。 14.面积的纵度。 15.高大貌。 16.边缘，外围。 17.回转;转动。 18.轮流;依次更替\n。 19.瞪着眼来回看。 20.量词。辆。用以计车数。 21.量词。多用于圆形之物，如日﹑月。 22.量词。次;遍。用于循环的事物或动作。 23.挥动◇作\"抡\"。 24.","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-轮"},{"id":"glyph-kai-8f6f","script":"kai","character":"软","reading":"ruǎn","description":"柔和;温和\n⒈柔，跟\"硬\"相对柔～。～木。\n⒉柔和，温和～言。～风。\n⒊懦弱～弱。欺～怕硬。\n⒋容易被感动或动摇心～。耳朵～。～骨头。\n⒌使用温柔的手段～求。～缠。～磨。\n⒍能力弱，质量差功夫～。～挡货。\n⒎没有气力手～无劲。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-软"},{"id":"glyph-kai-8f70","script":"kai","character":"轰","reading":"hōng","description":"雷鸣、炮击、爆破等的隆隆声\n枪炮、雷电等对准或瞄准爆发\n猛烈攻击\n驱赶;赶开\n⒈像声词。雷鸣、炮击等发出的巨大响声～鸣。～隆。\n⒉用大炮、炸弹、导弹等破坏～击。～炸。\n⒊赶，驱逐～出去。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-轰"},{"id":"glyph-kai-8f74","script":"kai","character":"轴","reading":"zhóu","description":"车子\n字画下端便于悬挂或卷起的圆杆\n把平面或立体分成对称部分的直线\n⒈支持轮子或其它机件的圆柱形部件，有固定的和转动的两种汽车～。飞轮～。曲～磨床。\n⒉像轴的东西～儿线。\n⒊将平面或立体分成对称部分的直线～线。\n⒋指字、画卷下面的木杆，因而借指装裱成卷的书或字画壁上挂有三～画。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-轴"},{"id":"glyph-kai-8f7b","script":"kai","character":"轻","reading":"qīng","description":"轻车\n轻工业的简称\n化学元素氢的旧译\n分量不大。与重”相对\n⒈份量小，跟\"重\"相对这张桌子较～。～于鸿毛。\n⒉数量少，程度浅工作～。～伤。\n⒊用力小～放。～声。\n⒋认为无所谓，不重要～敌。～视。\n⒌随便，不庄重～易。～率。～佻。\n⒍浅薄，便当～微。～便。～舟已过万重山。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-轻"},{"id":"glyph-kai-8f7d","script":"kai","character":"载","reading":"zǎi","description":"记载,写在一定的册页里,有郑重的色彩\n⒈年三年五～。\n⒉记在书报刊物上记～。登～。报～。刊～。转～。\n⒈装，乘坐～货。装～。此车可～六人。\n⒉承受～重五吨。\n⒊充满满～而归。风雪～途。\n⒋乃，边，于是～歌～舞。～弛～驱。\n载dài 1.加在头上;用头顶着。 2.尊奉;拥戴。\n载zāi 1.筑墙长版。 2.树立。参见\"载常\"。\n载zī 1.耕作。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-载"},{"id":"glyph-kai-8f7f","script":"kai","character":"轿","reading":"jiào","description":"竹舆。古代过山用的交通工具\n轿子","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-轿"}];
